def get_equal(tuples, expected_len):
    """The program dawnr proved in `t`, written in Python (checked against `t`, not itself proved).

    ensures  r == [65, 108, 108, 32, 116, 117, 112, 108, 101, 115, 32, 104, 97, 118, 101, 32, 115, 97, 109, 101, 32, 108, 101, 110, 103, 116, 104] or r == [65, 108, 108, 32, 116, 117, 112, 108, 101, 115, 32, 100, 111, 32, 110, 111, 116, 32, 104, 97, 118, 101, 32, 115, 97, 109, 101, 32, 108, 101, 110, 103, 116, 104]
    ensures  (r == [65, 108, 108, 32, 116, 117, 112, 108, 101, 115, 32, 104, 97, 118, 101, 32, 115, 97, 109, 101, 32, 108, 101, 110, 103, 116, 104]) == (forall i in [0, len(tuples)) . len(tuples[i]) == expected_len)
    """
    if not (_t_ints(tuples, 2)):
        raise TypeError('get_equal: `tuples` must be a list of lists of integers; nothing was proved for anything else')
    if not (_t_ints(expected_len, 0)):
        raise TypeError('get_equal: `expected_len` must be an integer; nothing was proved for anything else')
    tuples = _t_tuple(tuples)
    _t_result = _t_core(tuples, expected_len)
    return ''.join(chr(c) for c in _t_result)

def _t_core(tuples, expected_len):
    all_same = True
    i = 0
    # invariant: 0 <= i
    # invariant: i <= len(tuples)
    # invariant: all_same == (forall j in [0, i) . len(tuples[j]) == expected_len)
    # decreases: len(tuples) - i
    while (i < len(tuples)):
        if (len(tuples[i]) != expected_len):
            all_same = False
        i = (i + 1)
    if all_same:
        r = (65, 108, 108, 32, 116, 117, 112, 108, 101, 115, 32, 104, 97, 118, 101, 32, 115, 97, 109, 101, 32, 108, 101, 110, 103, 116, 104, )
    else:
        r = (65, 108, 108, 32, 116, 117, 112, 108, 101, 115, 32, 100, 111, 32, 110, 111, 116, 32, 104, 97, 118, 101, 32, 115, 97, 109, 101, 32, 108, 101, 110, 103, 116, 104, )
    return r

def _t_tuple(v):
    return tuple(_t_tuple(x) for x in v) if isinstance(v, (list, tuple)) else v

def _t_ints(v, depth):
    if depth == 0:
        return isinstance(v, int) and not isinstance(v, bool)
    return isinstance(v, (list, tuple)) and all(_t_ints(x, depth - 1) for x in v)

